            eventStatusLabel.setForeground(
                    RED
            );
        }
    }

    /*
     * ==================================================
     * COUNTDOWN TIMER
     * ==================================================
     */

    private void startCountdownTimer()
    {
        if (countdownTimer != null)
        {
            countdownTimer.stop();
        }

        countdownTimer =
                new Timer(
                        30000,
                        e ->
                        {
                            refreshCountdown();

                            revalidate();
                            repaint();
                        }
                );

        countdownTimer.setRepeats(
                true
        );

        countdownTimer.start();
    }

    public void stopCountdownTimer()
    {
        if (countdownTimer != null)
        {
            countdownTimer.stop();
            countdownTimer = null;
        }
    }

    /*
     * ==================================================
     * COUNTDOWN
     * ==================================================
     */

    private void refreshCountdown()
    {
        String eventEnd =
                plugin.getEventEnd();

        /*
         * ==================================================
         * EVENT ACTIVE = FALSE
         *
         * This is the master switch.
         * ==================================================
         */

        if (!plugin.isEventActive())
        {
            countdownTitleLabel.setText(
                    "EVENT"
            );

            countdownValueLabel.setText(
                    "ENDED"
            );

            countdownValueLabel.setForeground(
                    RED
            );

            if (
                    eventEnd != null
                            && !eventEnd.trim().isEmpty()
            )
            {
                try
                {
                    Instant endTime =
                            Instant.parse(
                                    eventEnd.trim()
                            );

                    String formattedEnd =
                            EVENT_END_FORMAT.format(
                                    endTime
                            );

                    eventEndTimeLabel.setText(
                            "Ended "
                                    + formattedEnd
                    );

                    eventEndTimeLabel.setForeground(
                            Color.LIGHT_GRAY
                    );
                }
                catch (DateTimeParseException exception)
                {
                    eventEndTimeLabel.setText(
                            "Event closed manually"
                    );

                    eventEndTimeLabel.setForeground(
                            Color.LIGHT_GRAY
                    );
                }
            }
            else
            {
                eventEndTimeLabel.setText(
                        "Event closed manually"
                );

                eventEndTimeLabel.setForeground(
                        Color.LIGHT_GRAY
                );
            }

            return;
        }

        /*
         * ==================================================
         * NO END DATE
         * ==================================================
         */

        if (
                eventEnd == null
                        || eventEnd.trim().isEmpty()
        )
        {
            countdownTitleLabel.setText(
                    "EVENT ENDS IN"
            );

            countdownValueLabel.setText(
                    "--"
            );

            countdownValueLabel.setForeground(
                    Color.LIGHT_GRAY
            );

            eventEndTimeLabel.setText(
                    "Ends --"
            );

            eventEndTimeLabel.setForeground(
                    Color.LIGHT_GRAY
            );

            return;
        }

        try
        {
            Instant endTime =
                    Instant.parse(
                            eventEnd.trim()
                    );

            String formattedEnd =
                    EVENT_END_FORMAT.format(
                            endTime
                    );

            Instant now =
                    Instant.now();

            /*
             * ==================================================
             * TIME HAS PASSED
             * ==================================================
             */

            if (!endTime.isAfter(now))
            {
                countdownTitleLabel.setText(
                        "EVENT"
                );

                countdownValueLabel.setText(
                        "ENDED"
                );

                countdownValueLabel.setForeground(
                        RED
                );

                eventEndTimeLabel.setText(
                        "Ended "
                                + formattedEnd
                );

                eventEndTimeLabel.setForeground(
                        Color.LIGHT_GRAY
                );

                return;
            }

            /*
             * ==================================================
             * EVENT RUNNING
             * ==================================================
             */

            countdownTitleLabel.setText(
                    "EVENT ENDS IN"
            );

            countdownValueLabel.setForeground(
                    GOLD
            );

            eventEndTimeLabel.setText(
                    "Ends "
                            + formattedEnd
            );

            eventEndTimeLabel.setForeground(
                    Color.LIGHT_GRAY
            );

            Duration remaining =
                    Duration.between(
                            now,
                            endTime
                    );

            long totalMinutes =
                    remaining.toMinutes();

            long days =
                    totalMinutes
                            / (24 * 60);

            long hours =
                    (
                            totalMinutes
                                    % (24 * 60)
                    ) / 60;

            long minutes =
                    totalMinutes % 60;

            if (days > 0)
            {
                countdownValueLabel.setText(
                        days
                                + (
                                days == 1
                                        ? " day "
                                        : " days "
                        )
                                + hours
                                + (
                                hours == 1
                                        ? " hour"
                                        : " hours"
                        )
                );

                return;
            }

            if (hours > 0)
            {
                countdownValueLabel.setText(
                        hours
                                + (
                                hours == 1
                                        ? " hour "
                                        : " hours "
                        )
                                + minutes
                                + (
                                minutes == 1
                                        ? " minute"
                                        : " minutes"
                        )
                );

                return;
            }

            countdownValueLabel.setText(
                    minutes
                            + (
                            minutes == 1
                                    ? " minute"
                                    : " minutes"
                    )
            );
        }
        catch (DateTimeParseException exception)
        {
            countdownTitleLabel.setText(
                    "EVENT END"
            );

            countdownValueLabel.setText(
                    "Invalid date"
            );

            countdownValueLabel.setForeground(
                    RED
            );

            eventEndTimeLabel.setText(
                    "Check EventControl"
            );

            eventEndTimeLabel.setForeground(
                    RED
            );
        }
    }

