    /*
     * ==================================================
     * PERSONAL STATUS REFRESH
     * ==================================================
     */

    private void refreshPersonalStatus()
    {
        String sync =
                plugin.getLastLeaderboardSync();

        if (!plugin.isLeaderboardSyncEnabled())
        {
            connectionStatusValue.setText(
                    "● NOT CONNECTED"
            );

            connectionStatusValue.setForeground(
                    Color.LIGHT_GRAY
            );

            personalRankValue.setText(
                    "Rank: --"
            );

            personalBoardValue.setText(
                    "Board: --"
            );

            nextRankValue.setText(
                    "Enable clan leaderboard sync to join."
            );

            return;
        }

        if (
                sync == null
                        || "Never".equalsIgnoreCase(sync)
                        || "Syncing...".equalsIgnoreCase(sync)
        )
        {
            connectionStatusValue.setText(
                    "● CONNECTING..."
            );

            connectionStatusValue.setForeground(
                    GOLD
            );
        }
        else
        {
            connectionStatusValue.setText(
                    "● CONNECTED"
            );

            connectionStatusValue.setForeground(
                    GREEN
            );
        }

        String localName =
                plugin.getLocalPlayerName();

        int level =
                plugin.getSlayerLevel();

        if (
                localName != null
                        && !localName.trim().isEmpty()
        )
        {
            for (
                    LeaderboardEntry entry :
                    plugin.getLeaderboard()
            )
            {
                if (
                        entry.getPlayer() != null
                                && entry.getPlayer()
                                .equalsIgnoreCase(
                                        localName
                                )
                )
                {
                    int syncedLevel =
                            entry.getSlayerLevel();

                    if (
                            syncedLevel >= 1
                                    && syncedLevel <= 99
                    )
                    {
                        if (
                                level < 1
                                        || level > 99
                                        || syncedLevel > level
                        )
                        {
                            level =
                                    syncedLevel;
                        }
                    }

                    break;
                }
            }
        }

        if (
                level >= 90
                        && level <= 99
        )
        {
            personalBoardValue.setText(
                    "Board: Slayer 90 - 99"
            );
        }
        else if (
                level >= 70
                        && level <= 89
        )
        {
            personalBoardValue.setText(
                    "Board: Slayer 70 - 89"
            );
        }
        else
        {
            personalRankValue.setText(
                    "Rank: Not eligible"
            );

            personalBoardValue.setText(
                    level > 0
                            ? "Board: Slayer " + level
                            : "Board: Slayer level unavailable"
            );

            nextRankValue.setText(
                    "Event boards require Slayer 70 - 99."
            );

            return;
        }

        if (
                localName == null
                        || localName.trim().isEmpty()
        )
        {
            personalRankValue.setText(
                    "Rank: --"
            );

            nextRankValue.setText(
                    "Log in to view your event rank."
            );

            return;
        }

        List<LeaderboardEntry> board =
                new ArrayList<>();

        for (
                LeaderboardEntry entry :
                plugin.getLeaderboard()
        )
        {
            int entryLevel =
                    entry.getSlayerLevel();

            if (
                    level >= 90
                            && level <= 99
                            && entryLevel >= 90
                            && entryLevel <= 99
            )
            {
                board.add(
                        entry
                );
            }
            else if (
                    level >= 70
                            && level <= 89
                            && entryLevel >= 70
                            && entryLevel <= 89
            )
            {
                board.add(
                        entry
                );
            }
        }

        board.sort(
                createRankingComparator()
        );

        int playerIndex =
                -1;

        LeaderboardEntry playerEntry =
                null;

        for (
                int i = 0;
                i < board.size();
                i++
        )
        {
            LeaderboardEntry entry =
                    board.get(i);

            if (
                    entry.getPlayer()
                            .equalsIgnoreCase(
                                    localName
                            )
            )
            {
                playerIndex =
                        i;

                playerEntry =
                        entry;

                break;
            }
        }

        if (
                playerIndex < 0
                        || playerEntry == null
        )
        {
            personalRankValue.setText(
                    "Rank: Registering..."
            );

            nextRankValue.setText(
                    "Your clan event entry is syncing."
            );

            return;
        }

        int rank =
                playerIndex + 1;

        personalRankValue.setText(
                "Rank: #" + rank
        );

        if (!plugin.isEventActive())
        {
            if (rank == 1)
            {
                nextRankValue.setText(
                        "You finished first on this board."
                );
            }
            else
            {
                nextRankValue.setText(
                        "You finished #"
                                + rank
                                + " on this board."
                );
            }

            return;
        }

        if (rank == 1)
        {
            nextRankValue.setText(
                    "You are currently leading this board."
            );

            return;
        }

        LeaderboardEntry playerAbove =
                board.get(
                        playerIndex - 1
                );

        int pointsNeeded =
                playerAbove.getPoints()
                        - playerEntry.getPoints()
                        + 1;

        if (pointsNeeded < 1)
        {
            pointsNeeded =
                    1;
        }

        nextRankValue.setText(
                pointsNeeded
                        + (
                        pointsNeeded == 1
                                ? " point"
                                : " points"
                )
                        + " to overtake #"
                        + (rank - 1)
        );
    }

    /*
     * ==================================================
     * FINAL RESULTS
     * ==================================================
     */

    private void refreshFinalResults()
    {
        if (plugin.isEventActive())
        {
            finalResultsSection.setVisible(
                    false
            );

            return;
        }

        finalResultsSection.setVisible(
                true
        );

        List<LeaderboardEntry> midBoard =
                new ArrayList<>();

        List<LeaderboardEntry> highBoard =
                new ArrayList<>();

        for (
                LeaderboardEntry entry :
                plugin.getLeaderboard()
        )
        {
            int level =
                    entry.getSlayerLevel();

            if (
                    level >= 70
                            && level <= 89
            )
            {
                midBoard.add(
                        entry
                );
            }
            else if (
                    level >= 90
                            && level <= 99
            )
            {
                highBoard.add(
                        entry
                );
            }
        }

        Comparator<LeaderboardEntry> ranking =
                createRankingComparator();

        midBoard.sort(
                ranking
        );

        highBoard.sort(
                ranking
        );

        /*
         * BOARD WINNERS
         */

        if (midBoard.isEmpty())
        {
            finalWinnerMidValue.setText(
                    "70-89: No winner"
            );
        }
        else
        {
            LeaderboardEntry winner =
                    midBoard.get(0);

            finalWinnerMidValue.setText(
                    "70-89: "
                            + winner.getPlayer()
                            + " • "
                            + winner.getPoints()
                            + " pts"
            );
        }

        if (highBoard.isEmpty())
        {
            finalWinnerHighValue.setText(
                    "90-99: No winner"
            );
        }
        else
        {
            LeaderboardEntry winner =
                    highBoard.get(0);

            finalWinnerHighValue.setText(
                    "90-99: "
                            + winner.getPlayer()
                            + " • "
                            + winner.getPoints()
                            + " pts"
            );
        }

        /*
         * PLAYER RESULT
         */

        String localName =
                plugin.getLocalPlayerName();

        if (
                localName == null
                        || localName.trim().isEmpty()
        )
        {
            finalYourResultValue.setText(
                    "Log in to view your result."
            );

            finalYourBoardValue.setText(
                    "--"
            );

            return;
        }

        LeaderboardEntry localEntry =
                null;

        for (
                LeaderboardEntry entry :
                plugin.getLeaderboard()
        )
        {
            if (
                    entry.getPlayer() != null
                            && entry.getPlayer()
                            .equalsIgnoreCase(
                                    localName
                            )
            )
            {
                localEntry =
                        entry;

                break;
            }
        }

        if (localEntry == null)
        {
            finalYourResultValue.setText(
                    "No final leaderboard entry."
            );

            finalYourBoardValue.setText(
                    "--"
            );

            return;
        }

        int level =
                localEntry.getSlayerLevel();

        List<LeaderboardEntry> playerBoard;
        String boardName;

        if (
                level >= 90
                        && level <= 99
        )
        {
            playerBoard =
                    highBoard;

            boardName =
                    "Slayer 90 - 99";
        }
        else if (
                level >= 70
                        && level <= 89
        )
        {
            playerBoard =
                    midBoard;

            boardName =
                    "Slayer 70 - 89";
        }
        else
        {
            finalYourResultValue.setText(
                    "Not eligible for event boards."
            );

            finalYourBoardValue.setText(
                    "Slayer " + level
            );

            return;
        }

        int rank =
                -1;

        for (
                int i = 0;
                i < playerBoard.size();
                i++
        )
        {
            if (
                    playerBoard
                            .get(i)
                            .getPlayer()
                            .equalsIgnoreCase(
                                    localName
                            )
            )
            {
                rank =
                        i + 1;

                break;
            }
        }

        if (rank < 1)
        {
            finalYourResultValue.setText(
                    "Final rank unavailable."
            );
        }
        else
        {
            finalYourResultValue.setText(
                    "#"
                            + rank
                            + " • "
                            + localEntry.getPoints()
                            + " pts • "
                            + localEntry.getKills()
                            + " kills"
            );
        }

        finalYourBoardValue.setText(
                boardName
        );
    }

    /*
     * ==================================================
     * RANKING COMPARATOR
     * ==================================================
     */

    private Comparator<LeaderboardEntry>
    createRankingComparator()
    {
        return Comparator
                .comparingInt(
                        LeaderboardEntry::getPoints
                )
                .reversed()
                .thenComparing(
                        Comparator
                                .comparingInt(
                                        LeaderboardEntry::getKills
                                )
                                .reversed()
                )
                .thenComparing(
                        LeaderboardEntry::getPlayer,
                        String.CASE_INSENSITIVE_ORDER
                );
    }

