     * BREAKDOWN
     * ==================================================
     */

    private void refreshBreakdown()
    {
        breakdownPanel.removeAll();

        boolean found =
                false;

        if (config.showKillBreakdown())
        {
            for (
                    SuperiorMonster monster :
                    SuperiorMonster.values()
            )
            {
                int kills =
                        plugin.getKillsForMonster(
                                monster
                        );

                if (
                        config.onlyShowKilledMonsters()
                                && kills == 0
                )
                {
                    continue;
                }

                breakdownPanel.add(
                        createBreakdownRow(
                                monster,
                                kills
                        )
                );

                breakdownPanel.add(
                        Box.createVerticalStrut(4)
                );

                found =
                        true;
            }
        }

        if (!found)
        {
            breakdownPanel.add(
                    createMessage(
                            "No Superior kills recorded yet."
                    )
            );
        }

        breakdownPanel.revalidate();
        breakdownPanel.repaint();
    }

    /*
     * ==================================================
     * LEADERBOARDS
     * ==================================================
     */

    private void refreshLeaderboards()
    {
        highBoardPanel.removeAll();
        midBoardPanel.removeAll();

        List<LeaderboardEntry> high =
                new ArrayList<>();

        List<LeaderboardEntry> mid =
                new ArrayList<>();

        for (
                LeaderboardEntry entry :
                plugin.getLeaderboard()
        )
        {
            int level =
                    entry.getSlayerLevel();

            if (
                    level >= 90
                            && level <= 99
            )
            {
                high.add(
                        entry
                );
            }
            else if (
                    level >= 70
                            && level <= 89
            )
            {
                mid.add(
                        entry
                );
            }
        }

        Comparator<LeaderboardEntry> ranking =
                createRankingComparator();

        high.sort(
                ranking
        );

        mid.sort(
                ranking
        );

        buildCompactBoard(
                highBoardPanel,
                high
        );

        buildCompactBoard(
                midBoardPanel,
                mid
        );

        highBoardPanel.revalidate();
        highBoardPanel.repaint();

        midBoardPanel.revalidate();
        midBoardPanel.repaint();
    }

    /*
     * ==================================================
     * BUILD BOARD
     * ==================================================
     */

    private void buildCompactBoard(
            JPanel panel,
            List<LeaderboardEntry> entries)
    {
        panel.removeAll();

        if (entries.isEmpty())
        {
            panel.add(
                    createBoardMessage(
                            "No eligible players yet."
                    )
            );

            panel.setPreferredSize(
                    new Dimension(
                            BOARD_WIDTH,
                            30
                    )
            );

            panel.setMaximumSize(
                    new Dimension(
                            BOARD_WIDTH,
                            30
                    )
            );

            return;
        }

        int topCount =
                Math.min(
                        3,
                        entries.size()
                );

        for (
                int i = 0;
                i < topCount;
                i++
        )
        {
            panel.add(
                    createCompactPodiumRow(
                            i + 1,
                            entries.get(i)
                    )
            );

            panel.add(
                    Box.createVerticalStrut(5)
            );
        }

        panel.add(
                Box.createVerticalStrut(4)
        );

        JLabel rankingTitle =
                new JLabel(
                        "FULL RANKING",
                        SwingConstants.CENTER
                );

        rankingTitle.setForeground(
                Color.LIGHT_GRAY
        );

        rankingTitle.setFont(
                rankingTitle
                        .getFont()
                        .deriveFont(
                                Font.BOLD,
                                9f
                        )
        );

        rankingTitle.setAlignmentX(
                CENTER_ALIGNMENT
        );

        rankingTitle.setPreferredSize(
                new Dimension(
                        BOARD_WIDTH,
                        18
                )
        );

        rankingTitle.setMaximumSize(
                new Dimension(
                        BOARD_WIDTH,
                        18
                )
        );

        panel.add(
                rankingTitle
        );

        panel.add(
                Box.createVerticalStrut(5)
        );

        for (
                int i = 0;
                i < entries.size();
                i++
        )
        {
            panel.add(
                    createCompactRankingRow(
                            i + 1,
                            entries.get(i)
                    )
            );

            panel.add(
                    Box.createVerticalStrut(3)
            );
        }

        int height =
                (topCount * 61)
                        + (entries.size() * 38)
                        + 45;

        panel.setPreferredSize(
                new Dimension(
                        BOARD_WIDTH,
                        height
                )
        );

        panel.setMaximumSize(
                new Dimension(
                        BOARD_WIDTH,
                        height
                )
        );
    }

    /*
     * ==================================================
     * PODIUM ROW
     * ==================================================
     */

