@Slf4j
@PluginDescriptor(
		name = "Superior Slayer Event",
		description = "Tracks Superior Slayer monsters for a clan event",
		tags = {"slayer", "superior", "clan", "event"}
)
public class SuperiorSlayerEventPlugin extends Plugin
{
	/*
	 * ==================================================
	 * CONFIG / STORAGE
	 * ==================================================
	 */

	private static final String CONFIG_GROUP =
			"superiorslayerevent";

	private static final String TOTAL_KILLS_KEY =
			"totalSuperiorKills";

	private static final String TOTAL_POINTS_KEY =
			"totalEventPoints";

	private static final String MONSTER_KILL_PREFIX =
			"kills_";

	private static final String EVENT_VERSION_KEY =
			"eventResetVersion";

	/*
	 * Two minutes.
	 *
	 * This timer now handles both:
	 *
	 * - member heartbeat
	 * - leaderboard/event refresh
	 */
	private static final int LEADERBOARD_REFRESH_MS =
			120000;

	private static final DateTimeFormatter TIME_FORMAT =
			DateTimeFormatter.ofPattern("HH:mm:ss");


	/*
	 * ==================================================
	 * INJECTED SERVICES
	 * ==================================================
	 */

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SuperiorSlayerEventConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SuperiorLeaderboardClient leaderboardClient;


	/*
	 * ==================================================
	 * EVENT DATA
	 * ==================================================
	 */

	private final Map<SuperiorMonster, Integer> monsterKills =
			new EnumMap<>(
					SuperiorMonster.class
			);

	/*
	 * Paid leaderboard players.
	 */
	private final List<LeaderboardEntry> leaderboard =
			new ArrayList<>();

	/*
	 * NEW:
	 *
	 * Every member currently registered through
	 * the plugin, whether they are Paid,
	 * Not Paid or Refunded.
	 */
	private final List<MemberEntry> members =
			new ArrayList<>();

	private int totalSuperiorKills = 0;
	private int totalEventPoints = 0;

	private int sessionSuperiorKills = 0;
	private int sessionEventPoints = 0;

	private int slayerLevel = 0;

	private String eventName =
			"Superior Slayer Event";

	private boolean eventActive =
			true;

	private int currentEventVersion =
			1;

	/*
	 * Supplied by EventControl!B5.
	 */
	private String eventEnd =
			"";

	private String lastLeaderboardSync =
			"Never";

	/*
	 * RuneLite can temporarily lose access
	 * to the local player during loading.
	 *
	 * Preserve the most recent valid RSN.
	 */
	private String lastKnownPlayerName =
			"";


	/*
	 * ==================================================
	 * SUBMISSION FINGERPRINT
	 * ==================================================
	 *
	 * Prevents identical score submissions from
	 * being uploaded repeatedly.
	 *
	 * Heartbeats are separate and are still sent
	 * every two minutes.
	 */

	private String lastSubmittedPlayer =
			"";

	private int lastSubmittedKills =
			-1;

	private int lastSubmittedPoints =
			-1;

	private int lastSubmittedSlayerLevel =
			-1;

	private int lastSubmittedEventVersion =
			-1;


	/*
	 * ==================================================
	 * UI / TIMERS
	 * ==================================================
	 */

	private Timer leaderboardRefreshTimer;

	private SuperiorSlayerEventPanel panel;

	private NavigationButton navButton;

	private BufferedImage sidebarIcon;


	/*
	 * ==================================================
	 * STARTUP
	 * ==================================================
	 */

	@Override
	protected void startUp()
	{
		loadData();

		sessionSuperiorKills = 0;
		sessionEventPoints = 0;

		updateSlayerLevel();

		resetSubmissionFingerprint();

		sidebarIcon =
				ImageUtil.loadImageResource(
						SuperiorSlayerEventPlugin.class,
						"sse_icon.png"
				);

		panel =
				new SuperiorSlayerEventPanel(
						this,
						config
				);

		navButton =
				NavigationButton.builder()
						.tooltip(
								"Superior Slayer Event"
						)
						.icon(
								sidebarIcon
						)
						.priority(
								5
						)
						.panel(
								panel
						)
						.build();

		if (config.showSidebar())
		{
			clientToolbar.addNavigation(
					navButton
			);
		}

		startLeaderboardTimer();

		/*
		 * When sync is already enabled,
		 * immediately connect this player
		 * to the Members system and fetch
		 * the current event state.
		 */
		if (isLeaderboardSyncEnabled())
		{
			sendMemberHeartbeat();
			refreshLeaderboard();
		}

		refreshPanel();

		log.info(
				"Superior Slayer Event started. Kills: {} Points: {} Slayer Level: {}",
				totalSuperiorKills,
				totalEventPoints,
				slayerLevel
		);
	}


	/*
	 * ==================================================
	 * SHUTDOWN
	 * ==================================================
	 */

	@Override
	protected void shutDown()
	{
		saveAllData();

		if (leaderboardRefreshTimer != null)
		{
			leaderboardRefreshTimer.stop();
			leaderboardRefreshTimer = null;
		}

		/*
		 * The panel contains its own live
		 * countdown Swing timer.
		 */
		if (panel != null)
		{
			panel.stopCountdownTimer();
		}

		if (navButton != null)
		{
			clientToolbar.removeNavigation(
					navButton
			);
		}

		leaderboard.clear();
		members.clear();

		panel = null;
		navButton = null;
		sidebarIcon = null;

		resetSubmissionFingerprint();

		log.info(
				"Superior Slayer Event stopped."
		);
	}


	/*
	 * ==================================================
	 * AUTOMATIC REFRESH / HEARTBEAT TIMER
	 * ==================================================
	 */

	private void startLeaderboardTimer()
	{
		if (leaderboardRefreshTimer != null)
		{
			leaderboardRefreshTimer.stop();
		}

		leaderboardRefreshTimer =
				new Timer(
						LEADERBOARD_REFRESH_MS,
						event ->
						{
							if (!isLeaderboardSyncEnabled())
							{
								return;
							}

							updateSlayerLevel();

							/*
							 * NEW:
							 *
							 * Keep Members.Last Seen alive
							 * even when kills and points
							 * haven't changed.
							 */
							sendMemberHeartbeat();

							/*
							 * Then download the current
							 * leaderboard and Members list.
							 */
							refreshLeaderboard();
						}
				);

		leaderboardRefreshTimer.setInitialDelay(
				LEADERBOARD_REFRESH_MS
		);

		leaderboardRefreshTimer.setRepeats(
				true
		);

		leaderboardRefreshTimer.start();
	}


	/*
	 * ==================================================
	 * MEMBER HEARTBEAT
	 * ==================================================
	 */

	private void sendMemberHeartbeat()
	{
		if (!isLeaderboardSyncEnabled())
		{
			return;
		}

		if (!isPlayerLoggedIn())
		{
			return;
		}

		updateSlayerLevel();

		if (
				slayerLevel < 1
						|| slayerLevel > 99
		)
		{
			return;
		}

		String playerName =
				getLocalPlayerName();

		if (
				playerName == null
						|| playerName.trim().isEmpty()
		)
		{
			return;
		}

		leaderboardClient.sendHeartbeat(
				playerName.trim(),
				slayerLevel
		);

		log.debug(
				"Member heartbeat sent for {}.",
				playerName
		);
	}


	/*
	 * ==================================================
	 * LOGIN
	 * ==================================================
	 */

	@Subscribe
	public void onGameStateChanged(
			GameStateChanged event)
	{
		if (
				event.getGameState()
						!= GameState.LOGGED_IN
		)
		{
			return;
		}

		updateSlayerLevel();

		Player localPlayer =
				client.getLocalPlayer();

		if (
				localPlayer != null
						&& localPlayer.getName() != null
						&& !localPlayer
						.getName()
						.trim()
						.isEmpty()
		)
		{
			lastKnownPlayerName =
					localPlayer
							.getName()
							.trim();
		}

		if (isLeaderboardSyncEnabled())
		{
			resetSubmissionFingerprint();

			/*
			 * NEW:
			 *
			 * Register/update Members immediately
			 * on login.
			 */
			sendMemberHeartbeat();

			refreshLeaderboard();
		}

		refreshPanel();
	}


	/*
	 * ==================================================
	 * SLAYER LEVEL CHANGE
	 * ==================================================
	 */

	@Subscribe
	public void onStatChanged(
			StatChanged event)
	{
		if (
				event.getSkill()
						!= Skill.SLAYER
		)
		{
			return;
		}

		int previousLevel =
				slayerLevel;

		updateSlayerLevel();

		if (
				slayerLevel
						== previousLevel
		)
		{
			return;
		}

		log.info(
				"Slayer level changed from {} to {}.",
				previousLevel,
				slayerLevel
		);

		refreshPanel();

		if (isLeaderboardSyncEnabled())
		{
			/*
			 * Update the Members sheet with
			 * the player's new Slayer level.
			 */
			sendMemberHeartbeat();

			/*
			 * Score submission is still only
			 * allowed while the event is active.
			 */
			if (eventActive)
			{
				submitScore();
			}
		}
	}


	/*
	 * ==================================================
	 * READ REAL SLAYER LEVEL
	 * ==================================================
	 */

	private void updateSlayerLevel()
	{
		if (
				client.getGameState()
						!= GameState.LOGGED_IN
		)
		{
			return;
		}

		int level =
				client.getRealSkillLevel(
						Skill.SLAYER
				);

		if (
				level >= 1
						&& level <= 99
		)
		{
			slayerLevel =
					level;
		}
	}


	/*
	 * ==================================================
	 * SUPERIOR SPAWN
	 * ==================================================
	 */

	@Subscribe
	public void onNpcSpawned(
			NpcSpawned event)
	{
		NPC npc =
				event.getNpc();

		if (
				npc == null
						|| npc.getName() == null
		)
		{
			return;
		}

		SuperiorMonster superior =
				SuperiorMonster.fromNpcName(
						npc.getName()
				);

		if (superior == null)
		{
			return;
		}

		/*
		 * If connected to an event which has
		 * officially ended, don't treat new
		 * Superior spawns as event activity.
		 */
		if (
				isLeaderboardSyncEnabled()
						&& !eventActive
		)
		{
			return;
		}

		if (config.showSpawnMessages())
		{
			String message =
					"<col=ff981f>Superior detected:</col> "
							+ superior.getSuperiorMonster()
							+ " | Slayer level: "
							+ superior.getSlayerLevel()
							+ " | Worth: "
							+ superior.getPoints()
							+ " point"
							+ (
							superior.getPoints() == 1
									? ""
									: "s"
					);

			client.addChatMessage(
					ChatMessageType.GAMEMESSAGE,
					"",
					message,
					null
			);
		}

		log.info(
				"Superior detected: {}",
				superior.getSuperiorMonster()
		);
	}


	/*
	 * ==================================================
	 * SUPERIOR DEATH
	 * ==================================================
	 */

	@Subscribe
	public void onActorDeath(
			ActorDeath event)
	{
		Actor actor =
				event.getActor();

		if (!(actor instanceof NPC))
		{
			return;
		}

		NPC npc =
				(NPC) actor;

		if (npc.getName() == null)
		{
			return;
		}

		SuperiorMonster superior =
				SuperiorMonster.fromNpcName(
						npc.getName()
				);

		if (superior == null)
		{
			return;
		}

		if (
				isLeaderboardSyncEnabled()
						&& !eventActive
		)
		{
			log.info(
					"Superior kill ignored because the event has ended."
			);

			return;
		}

		processSuperiorKill(
				superior
		);
	}


	/*
	 * ==================================================
	 * PROCESS SUPERIOR KILL
	 * ==================================================
	 */

	private void processSuperiorKill(
			SuperiorMonster superior)
	{
		int newMonsterCount =
				monsterKills.getOrDefault(
						superior,
						0
				) + 1;

		monsterKills.put(
				superior,
				newMonsterCount
		);

		int pointsEarned =
				superior.getPoints();

		totalSuperiorKills++;
		totalEventPoints += pointsEarned;

		sessionSuperiorKills++;
		sessionEventPoints += pointsEarned;

		saveMonsterKillCount(
				superior,
				newMonsterCount
		);

		saveTotals();

		refreshPanel();

		if (
				isLeaderboardSyncEnabled()
						&& eventActive
		)
		{
			updateSlayerLevel();

			submitScore();
		}

		if (config.showKillMessages())
		{
			StringBuilder message =
					new StringBuilder();

			message.append(
					"<col=00ff00>Superior slain:</col> "
			);

			message.append(
					superior.getSuperiorMonster()
			);

			if (config.showPointsInChat())
			{
				message.append(
						" | <col=ffff00>+"
				);

				message.append(
						pointsEarned
				);

				message.append(
						pointsEarned == 1
								? " point"
								: " points"
				);

				message.append(
						"</col>"
				);
			}

			message.append(
					" | "
			);

			message.append(
					superior.getSuperiorMonster()
			);

			message.append(
					" kills: "
			);

			message.append(
					newMonsterCount
			);

			message.append(
					" | Total kills: "
			);

			message.append(
					totalSuperiorKills
			);

			message.append(
					" | Total points: "
			);

			message.append(
					totalEventPoints
			);

			client.addChatMessage(
					ChatMessageType.GAMEMESSAGE,
					"",
					message.toString(),
					null
			);
		}

		log.info(
				"Superior killed: {} | Monster kills: {} | Total kills: {} | Points earned: {} | Total points: {} | Slayer: {}",
				superior.getSuperiorMonster(),
				newMonsterCount,
				totalSuperiorKills,
				pointsEarned,
				totalEventPoints,
				slayerLevel
		);
	}


	/*
	 * ==================================================
	 * AUTOMATIC SCORE SUBMISSION
	 * ==================================================
	 */

	private void submitScore()
	{
		if (!isLeaderboardSyncEnabled())
		{
			return;
		}

		if (!eventActive)
		{
			return;
		}

		if (!isPlayerLoggedIn())
		{
			return;
		}

		Player localPlayer =
				client.getLocalPlayer();

		if (
				localPlayer == null
						|| localPlayer.getName() == null
						|| localPlayer
						.getName()
						.trim()
						.isEmpty()
		)
		{
			return;
		}

		updateSlayerLevel();

		if (
				slayerLevel < 1
						|| slayerLevel > 99
		)
		{
			log.warn(
					"Participant submission skipped because Slayer level could not be read."
			);

			return;
		}

		String playerName =
				localPlayer
						.getName()
						.trim();

		lastKnownPlayerName =
				playerName;

		/*
		 * Don't upload identical score data
		 * repeatedly.
		 *
		 * Member heartbeats are handled
		 * separately.
		 */
		if (
				isSameAsLastSubmission(
						playerName,
						totalSuperiorKills,
						totalEventPoints,
						slayerLevel,
						currentEventVersion
				)
		)
		{
			return;
		}

		log.info(
				"Submitting clan participant: {} | Slayer: {} | Kills: {} | Points: {} | Event version: {}",
				playerName,
				slayerLevel,
				totalSuperiorKills,
				totalEventPoints,
				currentEventVersion
		);

		leaderboardClient.submitScore(
				playerName,
				totalSuperiorKills,
				totalEventPoints,
				slayerLevel
		);

		rememberSubmission(
				playerName,
				totalSuperiorKills,
				totalEventPoints,
				slayerLevel,
				currentEventVersion
		);

		/*
		 * Refresh shortly after submission so
		 * BuyIns, Members and Boards reflect
		 * the latest backend state.
		 */
		Timer delayedRefresh =
				new Timer(
						2000,
						event ->
						{
							if (
									isLeaderboardSyncEnabled()
							)
							{
								refreshLeaderboard();
							}
						}
				);

		delayedRefresh.setRepeats(
				false
		);

		delayedRefresh.start();
	}


	/*
	 * ==================================================
	 * SUBMISSION FINGERPRINT
	 * ==================================================
	 */

	private boolean isSameAsLastSubmission(
			String playerName,
			int kills,
			int points,
			int playerSlayerLevel,
			int eventVersion)
	{
		return playerName.equalsIgnoreCase(
				lastSubmittedPlayer
		)
				&& kills
				== lastSubmittedKills
				&& points
				== lastSubmittedPoints
				&& playerSlayerLevel
				== lastSubmittedSlayerLevel
				&& eventVersion
				== lastSubmittedEventVersion;
	}


	private void rememberSubmission(
			String playerName,
			int kills,
			int points,
			int playerSlayerLevel,
			int eventVersion)
	{
		lastSubmittedPlayer =
				playerName;

		lastSubmittedKills =
				kills;

		lastSubmittedPoints =
				points;

		lastSubmittedSlayerLevel =
				playerSlayerLevel;

		lastSubmittedEventVersion =
				eventVersion;
	}


	private void resetSubmissionFingerprint()
	{
		lastSubmittedPlayer =
				"";

		lastSubmittedKills =
				-1;

		lastSubmittedPoints =
				-1;

		lastSubmittedSlayerLevel =
				-1;

		lastSubmittedEventVersion =
				-1;
	}


	/*
	 * ==================================================
	 * FETCH EVENT / LEADERBOARD / MEMBERS
	 * ==================================================
	 */

	public void refreshLeaderboard()
	{
		if (!isLeaderboardSyncEnabled())
		{
			leaderboard.clear();
			members.clear();

			lastLeaderboardSync =
					"Disabled";

			refreshPanel();

			return;
		}

		leaderboardClient.fetchEventSnapshot(
				snapshot ->
						SwingUtilities.invokeLater(
								() ->
								{
									if (snapshot == null)
									{
										log.warn(
												"Event refresh returned no data."
										);

										return;
									}

									handleEventSnapshot(
											snapshot
									);
								}
						)
		);
	}


	/*
	 * ==================================================
	 * PROCESS EVENT SNAPSHOT
	 * ==================================================
	 */

	private void handleEventSnapshot(
			EventSnapshot snapshot)
	{
		eventName =
				snapshot.getEventName();

		eventActive =
				snapshot.isEventActive();

		currentEventVersion =
				snapshot.getResetVersion();

		eventEnd =
				snapshot.getEventEnd() == null
						? ""
						: snapshot
						.getEventEnd()
						.trim();

		checkForNewEvent(
				currentEventVersion
		);

		/*
		 * Paid leaderboard.
		 */
		leaderboard.clear();

		if (
				snapshot.getLeaderboard()
						!= null
		)
		{
			leaderboard.addAll(
					snapshot.getLeaderboard()
			);
		}

		/*
		 * NEW:
		 *
		 * All plugin members, regardless
		 * of buy-in status.
		 */
		members.clear();

		if (
				snapshot.getMembers()
						!= null
		)
		{
			members.addAll(
					snapshot.getMembers()
			);
		}

		lastLeaderboardSync =
				LocalTime.now()
						.format(
								TIME_FORMAT
						);

		refreshPanel();

		log.info(
				"Event refreshed. Name: {} Active: {} Version: {} End: {} Leaderboard: {} Members: {}",
				eventName,
				eventActive,
				currentEventVersion,
				eventEnd,
				leaderboard.size(),
				members.size()
		);

		/*
		 * Keep this player registered in
		 * the Members system regardless
		 * of whether they've paid.
		 */
		if (
				isLeaderboardSyncEnabled()
						&& isPlayerLoggedIn()
		)
		{
			updateSlayerLevel();

			sendMemberHeartbeat();

			/*
			 * Score submission only happens
			 * while the event is active.
			 */
			if (eventActive)
			{
				submitScore();
			}
		}
	}


	/*
	 * ==================================================
	 * AUTO RESET FOR NEW EVENT
	 * ==================================================
	 */

	private void checkForNewEvent(
			int serverVersion)
	{
		Integer savedVersion =
				configManager.getConfiguration(
						CONFIG_GROUP,
						EVENT_VERSION_KEY,
						Integer.class
				);

		if (savedVersion == null)
		{
			configManager.setConfiguration(
					CONFIG_GROUP,
					EVENT_VERSION_KEY,
					serverVersion
			);

			log.info(
					"Initial event version stored: {}",
					serverVersion
			);

			return;
		}

		if (
				savedVersion
						== serverVersion
		)
		{
			return;
		}

		log.info(
				"New event detected. Old version: {} New version: {}",
				savedVersion,
				serverVersion
		);

		resetLocalEventDataForNewEvent();

		configManager.setConfiguration(
				CONFIG_GROUP,
				EVENT_VERSION_KEY,
				serverVersion
		);

		resetSubmissionFingerprint();

		client.addChatMessage(
				ChatMessageType.GAMEMESSAGE,
				"",
				"<col=00ff00>Superior Slayer Event:</col> "
						+ "A new clan event has started. "
						+ "Your event kills and points have been reset.",
				null
		);
	}


	/*
	 * ==================================================
	 * RESET LOCAL EVENT DATA FOR NEW EVENT
	 * ==================================================
	 */

	private void resetLocalEventDataForNewEvent()
	{
		totalSuperiorKills = 0;
		totalEventPoints = 0;

		sessionSuperiorKills = 0;
		sessionEventPoints = 0;

		monsterKills.clear();

		for (
				SuperiorMonster monster :
				SuperiorMonster.values()
		)
		{
			monsterKills.put(
					monster,
					0
			);

			configManager.unsetConfiguration(
					CONFIG_GROUP,
					getMonsterConfigKey(
							monster
					)
			);
		}

		configManager.setConfiguration(
				CONFIG_GROUP,
				TOTAL_KILLS_KEY,
				0
		);

		configManager.setConfiguration(
				CONFIG_GROUP,
				TOTAL_POINTS_KEY,
				0
		);

		leaderboard.clear();
		members.clear();

		resetSubmissionFingerprint();

		refreshPanel();

		log.info(
				"Local Superior Slayer Event progress automatically reset for new event."
		);
	}


	/*
	 * ==================================================
	 * HELPERS
	 * ==================================================
