	/*
	 * ==================================================
	 * LEADERBOARD
	 * ==================================================
	 */

	public List<LeaderboardEntry> getLeaderboard()
	{
		return new ArrayList<>(
				leaderboard
		);
	}


	public int getPlayerRank()
	{
		String playerName =
				getLocalPlayerName();

		if (
				playerName == null
						|| playerName.isEmpty()
		)
		{
			return -1;
		}

		for (
				int i = 0;
				i < leaderboard.size();
				i++
		)
		{
			LeaderboardEntry entry =
					leaderboard.get(i);

			if (
					entry.getPlayer() != null
							&& entry
							.getPlayer()
							.equalsIgnoreCase(
									playerName
							)
			)
			{
				return i + 1;
			}
		}

		return -1;
	}


