		);
	}


	/*
	 * Useful if we later want to display
	 * the logged-in player's own member
	 * status in the Event tab.
	 */
	public MemberEntry getLocalMember()
	{
		String playerName =
				getLocalPlayerName();

		if (
				playerName == null
						|| playerName.isEmpty()
		)
		{
			return null;
		}

		for (
				MemberEntry member :
				members
		)
		{
			if (
					member.getPlayer() != null
							&& member
							.getPlayer()
							.equalsIgnoreCase(
									playerName
							)
			)
			{
				return member;
			}
		}

		return null;
	}


	/*
	 * ==================================================
	 * SETTINGS
	 * ==================================================
	 */

	@Subscribe
	public void onConfigChanged(
			ConfigChanged event)
	{
		if (
				!CONFIG_GROUP.equals(
						event.getGroup()
				)
		)
		{
			return;
		}

		/*
		 * ==================================================
		 * SIDEBAR
		 * ==================================================
		 */

		if (
				"showSidebar".equals(
						event.getKey()
				)
		)
		{
			if (config.showSidebar())
			{
				if (navButton != null)
				{
					clientToolbar.addNavigation(
							navButton
					);
				}
			}
			else
			{
				if (navButton != null)
				{
					clientToolbar.removeNavigation(
							navButton
					);
				}
			}
		}


		/*
		 * ==================================================
		 * LEADERBOARD SYNC
		 * ==================================================
		 */

		if (
				"enableLeaderboardSync".equals(
						event.getKey()
				)
		)
		{
			if (isLeaderboardSyncEnabled())
			{
				lastLeaderboardSync =
						"Syncing...";

				updateSlayerLevel();

				resetSubmissionFingerprint();

				/*
				 * NEW:
				 *
				 * Register the user immediately
				 * when sync is enabled.
				 */
				sendMemberHeartbeat();

				refreshLeaderboard();
			}
			else
			{
				leaderboard.clear();
				members.clear();

				lastLeaderboardSync =
						"Disabled";

				resetSubmissionFingerprint();

				refreshPanel();
			}
		}


		/*
		 * ==================================================
		 * EVENT URL OR EVENT KEY CHANGED
		 * ==================================================
		 */

		if (
				"clanEventUrl".equals(
						event.getKey()
				)
						|| "clanEventKey".equals(
						event.getKey()
				)
		)
		{
			if (isLeaderboardSyncEnabled())
			{
				lastLeaderboardSync =
						"Syncing...";

				updateSlayerLevel();

				resetSubmissionFingerprint();

				/*
				 * NEW:
				 * reconnect the member heartbeat
				 * using the updated backend details.
				 */
				sendMemberHeartbeat();

				refreshLeaderboard();
			}
		}

		SwingUtilities.invokeLater(
				() ->
				{
					if (panel != null)
					{
						panel.refresh();
					}
				}
		);
	}


	/*
	 * ==================================================
	 * LOAD DATA
	 * ==================================================
	 */

	private void loadData()
	{
		monsterKills.clear();

		Integer savedKills =
				configManager.getConfiguration(
						CONFIG_GROUP,
						TOTAL_KILLS_KEY,
						Integer.class
				);

		Integer savedPoints =
				configManager.getConfiguration(
						CONFIG_GROUP,
						TOTAL_POINTS_KEY,
						Integer.class
				);

		totalSuperiorKills =
				savedKills != null
						? savedKills
						: 0;

		totalEventPoints =
				savedPoints != null
						? savedPoints
						: 0;

		for (
				SuperiorMonster monster :
				SuperiorMonster.values()
		)
		{
			Integer kills =
					configManager.getConfiguration(
							CONFIG_GROUP,
							getMonsterConfigKey(
									monster
							),
							Integer.class
					);

			monsterKills.put(
					monster,
					kills != null
							? kills
							: 0
			);
		}
	}


	/*
	 * ==================================================
	 * SAVE DATA
	 * ==================================================
	 */

	private void saveAllData()
	{
		saveTotals();

		for (
				Map.Entry<
						SuperiorMonster,
						Integer
						> entry :
				monsterKills.entrySet()
		)
		{
			saveMonsterKillCount(
					entry.getKey(),
					entry.getValue()
			);
		}
	}


	private void saveTotals()
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				TOTAL_KILLS_KEY,
				totalSuperiorKills
		);

		configManager.setConfiguration(
				CONFIG_GROUP,
				TOTAL_POINTS_KEY,
				totalEventPoints
		);
	}


	private void saveMonsterKillCount(
			SuperiorMonster monster,
			int kills)
	{
		configManager.setConfiguration(
				CONFIG_GROUP,
				getMonsterConfigKey(
						monster
				),
				kills
		);
	}


	private String getMonsterConfigKey(
			SuperiorMonster monster)
	{
		return MONSTER_KILL_PREFIX
				+ monster
				.name()
				.toLowerCase();
	}


	/*
	 * ==================================================
	 * PANEL
	 * ==================================================
	 */

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}

		SwingUtilities.invokeLater(
				panel::refresh
		);
	}


	/*
	 * ==================================================
	 * STAT GETTERS
	 * ==================================================
	 */

	public int getTotalSuperiorKills()
	{
		return totalSuperiorKills;
	}


	public int getTotalEventPoints()
	{
		return totalEventPoints;
	}


	public int getSessionSuperiorKills()
	{
		return sessionSuperiorKills;
	}


	public int getSessionEventPoints()
	{
		return sessionEventPoints;
	}


	public int getKillsForMonster(
			SuperiorMonster monster)
	{
		return monsterKills.getOrDefault(
				monster,
				0
		);
	}


	public Map<SuperiorMonster, Integer> getMonsterKills()
	{
		return new EnumMap<>(
				monsterKills
		);
	}


	/*
	 * ==================================================
	 * MANUAL RESET
	 * ==================================================
	 */

	@Override
	public void resetConfiguration()
	{
		totalSuperiorKills = 0;
		totalEventPoints = 0;

		sessionSuperiorKills = 0;
		sessionEventPoints = 0;

		monsterKills.clear();

		leaderboard.clear();
		members.clear();

		for (
				SuperiorMonster monster :
				SuperiorMonster.values()
		)
		{
			monsterKills.put(
					monster,
					0
			);

			configManager.unsetConfiguration(
					CONFIG_GROUP,
					getMonsterConfigKey(
							monster
					)
			);
		}

		configManager.unsetConfiguration(
				CONFIG_GROUP,
				TOTAL_KILLS_KEY
		);

		configManager.unsetConfiguration(
				CONFIG_GROUP,
				TOTAL_POINTS_KEY
		);

		/*
		 * Do NOT remove EVENT_VERSION_KEY.
		 *
		 * Keeping the current version allows
		 * the backend to correctly detect when
		 * the organiser starts a genuinely
		 * new event.
		 */
		resetSubmissionFingerprint();

		refreshPanel();

		log.info(
				"Superior Slayer Event data has been manually reset."
		);
	}


	/*
	 * ==================================================
	 * CONFIG
	 * ==================================================
	 */

	@Provides
	SuperiorSlayerEventConfig provideConfig(
			ConfigManager configManager)
	{
		return configManager.getConfig(
				SuperiorSlayerEventConfig.class
		);
	}
}

